import * as fs from 'fs';

function isPlainObject(o: any): boolean {
  return o !== null && typeof o === 'object' && !Array.isArray(o);
}

function isEqual(x: any, y: any): boolean {
  if (x === y) return true;
  if (Array.isArray(x) && Array.isArray(y)) {
    if (x.length !== y.length) return false;
    return x.every((val, index) => isEqual(val, y[index]));
  }
  if (isPlainObject(x) && isPlainObject(y)) {
    const keysX = Object.keys(x);
    const keysY = Object.keys(y);
    if (keysX.length !== keysY.length) return false;
    return keysX.every(key => Object.prototype.hasOwnProperty.call(y, key) && isEqual(x[key], y[key]));
  }
  return false;
}

function deepMerge(a: any, b: any): any {
  if (Array.isArray(a) && Array.isArray(b)) {
    const result = [...a];
    for (const item of b) {
      if (!result.some(existing => isEqual(existing, item))) {
        result.push(item);
      }
    }
    return result;
  } else if (isPlainObject(a) && isPlainObject(b)) {
    const result: any = { ...a };
    for (const key in b) {
      if (Object.prototype.hasOwnProperty.call(a, key)) {
        result[key] = deepMerge(a[key], b[key]);
      } else {
        result[key] = b[key];
      }
    }
    return result;
  } else {
    return b;
  }
}

function sortObjectKeys(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(sortObjectKeys);
  }
  if (isPlainObject(obj)) {
    const sorted: any = {};
    Object.keys(obj).sort().forEach(key => {
      sorted[key] = sortObjectKeys(obj[key]);
    });
    return sorted;
  }
  return obj;
}

