const FILE_PATH = '/tmp/…/app.log';

function main() {
    let content = '';
    try {
        content = fs.readFileSync(FILE_PATH, 'utf8');
    } catch (e) {
        return;
    }

    const lines = content.split(/\r?\n/);
    const levelCounts: { [key: string]: number } = {};
    const componentErrors: { [key: string]: number } = {};
    const uniqueErrors = new Set<string>();
    const hourCounts: { [key: string]: number } = {};

    for (const line of lines) {
        if (!line.trim()) continue;

        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        const match = line.match(/^\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)$/);
        if (!match) continue;

        const [, , hour, level, component, message] = match;

        // Level counts
        levelCounts[level] = (levelCounts[level] || 0) + 1;

        // Errors tracking
        if (level === 'ERROR') {
            componentErrors[component] = (componentErrors[component] || 0) + 1;
            uniqueErrors.add(message);
        }

        // Hour tracking
        const hourKey = `${hour}:00`;
        hourCounts[hourKey] = (hourCounts[hourKey] || 0) + 1;
    }

    // 1. Entries by Level (sorted alphabetically)
    const sortedLevels = Object.keys(levelCounts).sort();
    let levelsStr = '';
    for (const lvl of sortedLevels) {
        levelsStr += `  ${lvl}: ${levelCounts[lvl]}\n`;
    }

    // 2. Component with Most Errors
    let maxErrorComp = '';
    let maxErrorCount = 0;
    for (const comp in componentErrors) {
        if (componentErrors[comp] > maxErrorCount) {
            maxErrorCount = componentErrors[comp];
            maxErrorComp = comp;
        }
    }

    // 3. Unique Error Messages (sorted alphabetically)
    const sortedUniqueErrors = Array.from(uniqueErrors).sort();
    let errorsStr = '';
    for (const err of sortedUniqueErrors) {
        errorsStr += `  - ${err}\n`;
    }

    // 4. Busiest Hour
    let busiestHour = '';
    let maxHourCount = 0;
    const sortedHours = Object.keys(hourCounts).sort();
    for (const h of sortedHours) {
        if (hourCounts[h] > maxHourCount) {
            maxHourCount = hourCounts[h];
            busiestHour = h;
        }
    }

    // Final Output
    process.stdout.write(`=== Log Analysis ===\n\n`);
    process.stdout.write(`Entries by Level:\n${levelsStr.trimEnd()}\n\n`);
    process.stdout.write(`Component with Most Errors: ${maxErrorComp} (${maxErrorCount} errors)\n\n`);
    process.stdout.write(`Unique Error Messages:\n${errorsStr.trimEnd()}\n\n`);
    process.stdout.write(`Busiest Hour: ${busiestHour} (${maxHourCount} entries)\n`);
}

