function main() {
    const filePath = '/tmp/…/employees.csv';

    let data: string;
    try {
        data = fs.readFileSync(filePath, 'utf8');
    } catch (e) {
        return;
    }

    const lines = data.split(/\r?\n/).filter(line => line.trim() !== '');
    if (lines.length === 0) return;

    const rows = lines.slice(1);
    const deptStats = new Map<string, { totalSalary: number, count: number }>();
    let totalBudget = 0;
    let highestPaidName = '';
    let highestPaidSalary = -1;

    for (const line of rows) {
        const columns = line.split(',');
        if (columns.length < 4) continue;

        const name = columns[1].trim();
        const department = columns[2].trim();
        const salary = parseFloat(columns[3].trim());

        if (isNaN(salary)) continue;

        totalBudget += salary;

        if (salary > highestPaidSalary) {
            highestPaidSalary = salary;
            highestPaidName = name;
        }

        const stats = deptStats.get(department) || { totalSalary: 0, count: 0 };
        stats.totalSalary += salary;
        stats.count += 1;
        deptStats.set(department, stats);
    }

    const sortedDepartments = Array.from(deptStats.keys()).sort();

    process.stdout.write('=== Salary Report ===\n\n');

    process.stdout.write('Average Salary by Department:\n');
    for (const dept of sortedDepartments) {
        const stats = deptStats.get(dept)!;
        const average = stats.totalSalary / stats.count;
        process.stdout.write(`  ${dept}: ${formatCurrency(average, 2)}\n`);
    }

    process.stdout.write(`\nHighest Paid: ${highestPaidName} (${formatCurrency(highestPaidSalary, 0)})\n`);

    process.stdout.write('\nDepartments with >2 employees:\n');
    for (const dept of sortedDepartments) {
        const stats = deptStats.get(dept)!;
        if (stats.count > 2) {
            process.stdout.write(`  ${dept} (${stats.count} employees)\n`);
        }
    }

    process.stdout.write(`\nTotal Budget: ${formatCurrency(totalBudget, 0)}\n`);
}

