use std::fs::File;
use std::io::{self, BufRead};

fn main() {
    let path = "/tmp/…/app.log";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = io::BufReader::new(file);

    let mut level_counts = BTreeMap::new();
    let mut component_errors = BTreeMap::new();
    let mut error_messages = BTreeSet::new();
    let mut hour_counts = BTreeMap::new();

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.trim().is_empty() {
            continue;
        }

        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let closing_bracket = match line.find(']') {
            Some(idx) => idx,
            None => continue,
        };

        if closing_bracket < 1 {
            continue;
        }
        let timestamp = &line[1..closing_bracket];
        if timestamp.len() < 13 {
            continue;
        }
        let hour = &timestamp[11..13];

        let remainder = if line.len() > closing_bracket + 2 {
            &line[closing_bracket + 2..]
        } else {
            continue;
        };

        let parts: Vec<&str> = remainder.splitn(2, " - ").collect();
        if parts.len() < 2 {
            continue;
        }
        let header = parts[0];
        let message = parts[1];

        let header_parts: Vec<&str> = header.splitn(2, ' ').collect();
        if header_parts.len() < 2 {
            continue;
        }
        let level = header_parts[0];
        let component_part = header_parts[1];
        let component = if component_part.starts_with('(') && component_part.ends_with(')') {
            &component_part[1..component_part.len() - 1]
        } else {
            component_part
        };

        *level_counts.entry(level.to_string()).or_insert(0) += 1;
        *hour_counts.entry(hour.to_string()).or_insert(0) += 1;

        if level == "ERROR" {
            *component_errors.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let most_errors_comp = component_errors
        .iter()
        .max_by_key(|entry| entry.1)
        .map(|(comp, count)| (comp, count));

    if let Some((comp, count)) = most_errors_comp {
        println!("Component with Most Errors: {} ({} errors)", comp, count);
    } else {
        println!("Component with Most Errors: None (0 errors)");
    }
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let busiest_hour = hour_counts
        .iter()
        .max_by_key(|entry| entry.1)
        .map(|(hour, count)| (hour, count));

    if let Some((hour, count)) = busiest_hour {
        println!("Busiest Hour: {}:00 ({} entries)", hour, count);
    } else {
        println!("Busiest Hour: 00:00 (0 entries)");
    }
}

