var levelCounts = [String: Int]()
var errorComponentCounts = [String: Int]()
var errorMessages = Set<String>()
var hourCounts = [String: Int]()

for line in lines {
    // Extract Hour
    if let spaceIndex = line.firstIndex(of: " ") {
        let hourStart = line.index(after: spaceIndex)
        if let hourEnd = line.index(hourStart, offsetBy: 2, limitedBy: line.endIndex) {
            let hour = String(line[hourStart..<hourEnd])
            hourCounts[hour, default: 0] += 1
        }
    }

    // Extract Level, Component, and Message
    if let bracketEndIndex = line.firstIndex(of: "]") {
        let remaining = line[line.index(after: bracketEndIndex)...].trimmingCharacters(in: .whitespaces)

        if let openParenIndex = remaining.firstIndex(of: "("),
           let closeParenIndex = remaining.firstIndex(of: ")") {

            let level = remaining[..<openParenIndex].trimmingCharacters(in: .whitespaces)
            let component = remaining[remaining.index(after: openParenIndex)..<closeParenIndex]

            let afterParen = remaining[remaining.index(after: closeParenIndex)...]
            if let hyphenIndex = afterParen.firstIndex(of: "-") {
                let message = afterParen[afterParen.index(after: hyphenIndex)...].trimmingCharacters(in: .whitespaces)

                levelCounts[level, default: 0] += 1

                if level == "ERROR" {
                    errorComponentCounts[String(component), default: 0] += 1
                    errorMessages.insert(message)
                }
            }
        }
    }
}

