use std::collections::BTreeMap;
use std::fs;

fn format_commas(n: i64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    for i in 0..len {
        result.push(chars[i]);
        if i < len - 1 && (len - 1 - i) % 3 == 0 {
            result.push(',');
        }
    }
    result
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let content = fs::read_to_string(path).expect("Unable to read file");
    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() {
        return;
    }

    let mut dept_stats: BTreeMap<String, (f64, usize)> = BTreeMap::new();
    let mut max_salary = -1.0;
    let mut max_salary_name = String::new();
    let mut total_budget = 0.0;

    for line in lines.iter().skip(1) {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let cols: Vec<&str> = line.split(',').collect();
        if cols.len() < 4 {
            continue;
        }

        let name = cols[1].trim().to_string();
        let dept = cols[2].trim().to_string();
        let salary: f64 = cols[3].trim().parse().unwrap_or(0.0);

        let stats = dept_stats.entry(dept).or_insert((0.0, 0));
        stats.0 += salary;
        stats.1 += 1;

        if salary > max_salary {
            max_salary = salary;
            max_salary_name = name;
        }
        total_budget += salary;
    }

    println!("=== Salary Report ===\n");
    println!("Average Salary by Department:");
    for (dept, (sum, count)) in &dept_stats {
        let avg = sum / (*count as f64);
        let avg_str = format!("{:.2}", avg);
        let parts: Vec<&str> = avg_str.split('.').collect();
        let integer_part = parts[0].parse::<i64>().unwrap_or(0);
        println!("  {}: ${}.{}", dept, format_commas(integer_part), parts[1]);
    }

    println!("\nHighest Paid: {} (${})", max_salary_name, format_commas(max_salary as i64));

    println!("\nDepartments with >2 employees:");
    for (dept, (sum, count)) in &dept_stats {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }

    println!("\nTotal Budget: ${}", format_commas(total_budget as i64));
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {

    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://127.0.0.1:18923/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                response.append(line);
            }
            in.close();
            conn.disconnect();

            String json = response.toString();
            List<Product> filteredProducts = new ArrayList<>();
            double totalSum = 0;

            int startPos = 0;
            while ((startPos = json.indexOf("{", startPos)) != -1) {
                int endPos = json.indexOf("}", startPos);
                if (endPos == -1) break;
                String objectStr = json.substring(startPos, endPos + 1);

                String name = extractValue(objectStr, "name");
                String priceStr = extractValue(objectStr, "price");

                if (name != null && priceStr != null) {
                    double price = Double.parseDouble(priceStr);
                    if (price > 50.00) {
                        filteredProducts.add(new Product(name, price));
                        totalSum += price;
                    }
                }
                startPos = endPos + 1;
            }

            Collections.sort(filteredProducts, Comparator.comparing(p -> p.name));

            System.out.println("=== Filtered Products (price > $50.00) ===");
            System.out.println();
            for (Product p : filteredProducts) {
                System.out.printf("%s: $%.2f\n", p.name, p.price);
            }
            System.out.println();
            System.out.println("Count: " + filteredProducts.size());
            System.out.printf("Total: $%.2f\n", totalSum);

        } catch (Exception e) {
            // Silently fail or handle as needed; prompt requires specific output format
        }
    }

    private static String extractValue(String json, String key) {
        String search = "\"" + key + "\":";
        int keyIndex = json.indexOf(search);
        if (keyIndex == -1) return null;

        int valStart = keyIndex + search.length();
        while (valStart < json.length() && (json.charAt(valStart) == ' ' || json.charAt(valStart) == '"')) {
            valStart++;
        }

        int valEnd;
        if (json.charAt(valStart - 1) == '"') {
            valEnd = json.indexOf("\"", valStart);
        } else {
            valEnd = json.indexOf(",", valStart);
            if (valEnd == -1 || (json.indexOf("}", valStart) != -1 && json.indexOf("}", valStart) < valEnd)) {
                valEnd = json.indexOf("}", valStart);
            }
        }

        if (valEnd == -1) return null;
        return json.substring(valStart, valEnd).trim();
    }
}

