        var totalBudget: Double = 0
        var highestPaidName = ""
        var highestPaidSalary: Double = -1.0

        for emp in employees {
            deptSalaries[emp.dept, default: []].append(emp.salary)
            totalBudget += emp.salary
            if emp.salary > highestPaidSalary {
                highestPaidSalary = emp.salary
                highestPaidName = emp.name
            }
        }

        print("=== Salary Report ===\n")

        print("Average Salary by Department:")
        let sortedDepts = deptSalaries.keys.sorted()
        for dept in sortedDepts {
            let salaries = deptSalaries[dept]!
            let avg = salaries.reduce(0, +) / Double(salaries.count)
            print("  \(dept): $\(formatNumber(avg, decimals: 2))")
        }

        print("\nHighest Paid: \(highestPaidName) ($\(formatNumber(highestPaidSalary, decimals: 0)))")

        print("\nDepartments with >2 employees:")
        for dept in sortedDepts {
            let count = deptSalaries[dept]!.count
            if count > 2 {
                print("  \(dept) (\(count) employees)")
            }
        }

        print("\nTotal Budget: $\(formatNumber(totalBudget, decimals: 0))")
    }
} catch {
    // Silent fail
}

import json
import heapq

def main():
    file_path = '/tmp/…/graph.json'

    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return

    nodes = data.get('nodes', [])
    edges = data.get('edges', [])

    # Build adjacency list for an undirected graph
    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge.get('from')
        v = edge.get('to')
        w = edge.get('weight')
        if u in adj and v in adj:
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Dijkstra's Algorithm
    start_node = 'A'
    if start_node not in adj:
        return

    distances = {node: float('inf') for node in nodes}
    distances[start_node] = 0

    # Priority queue stores (distance, node)
    pq = [(0, start_node)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        # If we found a longer path already, skip
        if current_dist > distances[u]:
            continue

        for v, weight in adj[u]:
            distance = current_dist + weight
            if distance < distances[v]:
                distances[v] = distance
                heapq.heappush(pq, (distance, v))

    # Output formatting
    print("=== Shortest Paths from A ===\n")
    for node in sorted(nodes):
        dist = distances[node]
        print(f"A -> {node}: {dist}")

if __name__ == "__main__":
    main()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int count;
} Entry;

char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *d = malloc(len);
    if (d) strcpy(d, s);
    return d;
}

int compare_entries(const void *a, const void *b) {
    return strcmp(((Entry *)a)->name, ((Entry *)b)->name);
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(void) {
    const char *filename = "/tmp/…/app.log";
    FILE *fp = fopen(filename, "r");
    if (!fp) return 0;

    Entry *levels = NULL;
    int level_count = 0;
    Entry *components = NULL;
    int component_count = 0;
    char **unique_errors = NULL;
    int unique_error_count = 0;
    int hour_counts[24] = {0};

    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\r\n")] = 0;
        if (strlen(line) == 0) continue;

        if (strlen(line) < 14) continue;
        int hour = (line[12] - '0') * 10 + (line[13] - '0');
        if (hour >= 0 && hour < 24) {
            hour_counts[hour]++;
        }

        char *bracket_end = strchr(line, ']');
        if (!bracket_end) continue;
        char *level_start = bracket_end + 1;
        while (*level_start == ' ') level_start++;
        char *level_end = strchr(level_start, ' ');
        if (!level_end) continue;

        char level_tmp[64];
        int level_len = level_end - level_start;
        if (level_len >= 64) level_len = 63;
        strncpy(level_tmp, level_start, level_len);
        level_tmp[level_len] = '\0';

        int found_level = 0;
        for (int i = 0; i < level_count; i++) {
            if (strcmp(levels[i].name, level_tmp) == 0) {
                levels[i].count++;
                found_level = 1;
                break;
            }
        }
        if (!found_level) {
            Entry *tmp = realloc(levels, sizeof(Entry) * (level_count + 1));
            if (tmp) {
                levels = tmp;
                levels[level_count].name = my_strdup(level_tmp);
                levels[level_count].count = 1;
                level_count++;
            }
        }

        char *comp_start = strchr(level_end, '(');
        if (!comp_start) continue;
        comp_start++;
        char *comp_end = strchr(comp_start, ')');
        if (!comp_end) continue;

        char comp_tmp[128];
        int comp_len = comp_end - comp_start;
        if (comp_len >= 128) comp_len = 127;
        strncpy(comp_tmp, comp_start, comp_len);
        comp_tmp[comp_len] = '\0';

        if (strcmp(level_tmp, "ERROR") == 0) {
            int found_comp = 0;
            for (int i = 0; i < component_count; i++) {
                if (strcmp(components[i].name, comp_tmp) == 0) {
                    components[i].count++;
                    found_comp = 1;
                    break;
                }
            }
            if (!found_comp) {
                Entry *tmp = realloc(components, sizeof(Entry) * (component_count + 1));
                if (tmp) {
                    components = tmp;
                    components[component_count].name = my_strdup(comp_tmp);
                    components[component_count].count = 1;
                    component_count++;
                }
            }

            char *msg_start = strstr(comp_end, " - ");
            if (msg_start) {
                msg_start += 3;
                int found_msg = 0;
                for (int i = 0; i < unique_error_count; i++) {
                    if (strcmp(unique_errors[i], msg_start) == 0) {
                        found_msg = 1;
                        break;
                    }
                }
                if (!found_msg) {
                    char **tmp = realloc(unique_errors, sizeof(char *) * (unique_error_count + 1));
                    if (tmp) {
                        unique_errors = tmp;
                        unique_errors[unique_error_count] = my_strdup(msg_start);
                        unique_error_count++;
                    }
                }
            }
        }
    }
    fclose(fp);

    printf("=== Log Analysis ===\n\n");

    printf("Entries by Level:\n");
    qsort(levels, level_count, sizeof(Entry), compare_entries);
    for (int i = 0; i < level_count; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }

    printf("\n");
    int max_errs = -1;
    char *best_comp = "None";
    for (int i = 0; i < component_count; i++) {
        if (components[i].count > max_errs) {
            max_errs = components[i].count;
            best_comp = components[i].name;
        }
    }
    printf("Component with Most Errors: %s (%d errors)\n", best_comp, max_errs == -1 ? 0 : max_errs);

    printf("\nUnique Error Messages:\n");
    qsort(unique_errors, unique_error_count, sizeof(char *), compare_strings);
    for (int i = 0; i < unique_error_count; i++) {
        printf("  - %s\n", unique_errors[i]);
    }

    printf("\n");
    int max_hour_entries = -1;
    int busiest_hour = 0;
    for (int i = 0; i < 24; i++) {
        if (hour_counts[i] > max_hour_entries) {
            max_hour_entries = hour_counts[i];
            busiest_hour = i;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest_hour, max_hour_entries == -1 ? 0 : max_hour_entries);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    double total_salary;
    int count;
} Dept;

void format_money(char *buf, double value, int precision) {
    char raw[64];
    if (precision == 0) {
        snprintf(raw, sizeof(raw), "%.0f", value);
    } else {
        snprintf(raw, sizeof(raw), "%.*f", precision, value);
    }

    char *dot = strchr(raw, '.');
    int int_len = dot ? (int)(dot - raw) : (int)strlen(raw);
    int out_idx = 0;

    for (int i = int_len - 1; i >= 0; i--) {
        if (i != int_len - 1 && (int_len - 1 - i) % 3 == 0) {
            buf[out_idx++] = ',';
        }
        buf[out_idx++] = raw[i];
    }

    for (int i = 0; i < out_idx / 2; i++) {
        char t = buf[i];
        buf[i] = buf[out_idx - 1 - i];
        buf[out_idx - 1 - i] = t;
    }

    if (dot) {
        strcpy(buf + out_idx, dot);
    } else {
        buf[out_idx] = '\0';
    }
}

int compare_depts(const void *a, const void *b) {
    return strcmp(((Dept *)a)->name, ((Dept *)b)->name);
}

int main(void) {
    const char *filename = "/tmp/…/employees.csv";
    FILE *fp = fopen(filename, "r");
    if (!fp) return 1;

    char *line = malloc(1024);
    if (!line) return 1;

    // Skip header
    if (!fgets(line, 1024, fp)) {
        free(line);
        fclose(fp);
        return 0;
    }

    Dept *depts = malloc(sizeof(Dept) * 1000);
    int dept_count = 0;
    double total_budget = 0;
    double max_salary = -1.0;
    char max_salary_name[256] = "";

    while (fgets(line, 1024, fp)) {
        char line_copy[1024];
        strcpy(line_copy, line);

        char *fields[6];
        int field_idx = 0;
        char *ptr = line_copy;
        while (*ptr && field_idx < 6) {
            fields[field_idx++] = ptr;
            while (*ptr && *ptr != ',') ptr++;
            if (*ptr) {
                *ptr = '\0';
                ptr++;
            }
        }

        // Clean trailing newline from the last field
        if (field_idx > 0) {
            char *last = fields[field_idx - 1];
            char *nl = strpbrk(last, "\r\n");
            if (nl) *nl = '\0';
        }

        if (field_idx < 4) continue;

        char *name = fields[1];
        char *dept_name = fields[2];
        double salary = atof(fields[3]);

        total_budget += salary;
        if (salary > max_salary) {
            max_salary = salary;
            strncpy(max_salary_name, name, sizeof(max_salary_name) - 1);
        }

        int found = 0;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(depts[i].name, dept_name) == 0) {
                depts[i].total_salary += salary;
                depts[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            depts[dept_count].name = malloc(strlen(dept_name) + 1);
            strcpy(depts[dept_count].name, dept_name);
            depts[dept_count].total_salary = salary;
            depts[dept_count].count = 1;
            dept_count++;
        }
    }

    qsort(depts, dept_count, sizeof(Dept), compare_depts);

    printf("=== Salary Report ===\n\n");

    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_count; i++) {
        char salary_buf[64];
        format_money(salary_buf, depts[i].total_salary / depts[i].count, 2);
        printf("  %s: $%s\n", depts[i].name, salary_buf);
    }

    printf("\n");
    char max_sal_buf[64];
    format_money(max_sal_buf, max_salary, 0);
    printf("Highest Paid: %s ($%s)\n", max_salary_name, max_sal_buf);

    printf("\nDepartments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }

    printf("\n");
    char budget_buf[64];
    format_money(budget_buf, total_budget, 0);
    printf("Total Budget: $%s\n", budget_buf);

    for (int i = 0; i < dept_count; i++) free(depts[i].name);
    free(depts);
    free(line);
    fclose(fp);

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";
        TreeMap<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrorCounts = new HashMap<>();
        TreeSet<String> uniqueErrorMessages = new TreeSet<>();
        int[] hourCounts = new int[24];

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;

                // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
                int closingBracket = line.indexOf(']');
                if (closingBracket == -1) continue;

                String timestamp = line.substring(1, closingBracket);
                if (timestamp.length() < 13) continue;
                String hourStr = timestamp.substring(11, 13);
                try {
                    int hour = Integer.parseInt(hourStr);
                    hourCounts[hour]++;
                } catch (NumberFormatException e) {
                    // Skip malformed hour
                }

                String rest = line.substring(closingBracket + 2);
                int levelEnd = rest.indexOf(" (");
                if (levelEnd == -1) continue;
                String level = rest.substring(0, levelEnd);
                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                int componentStart = levelEnd + 2;
                int componentEnd = rest.indexOf(")", componentStart);
                if (componentEnd == -1) continue;
                String component = rest.substring(componentStart, componentEnd);

                int messageStart = rest.indexOf(" - ", componentEnd);
                if (messageStart == -1) continue;
                String message = rest.substring(messageStart + 3);

                if ("ERROR".equals(level)) {
                    componentErrorCounts.put(component, componentErrorCounts.getOrDefault(component, 0) + 1);
                    uniqueErrorMessages.add(message);
                }
            }
        } catch (IOException e) {
            // Handle file errors silently as per requirements
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String topComponent = "";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : componentErrorCounts.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                topComponent = entry.getKey();
            }
        }
        System.out.println("Component with Most Errors: " + topComponent + " (" + maxErrors + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : uniqueErrorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        int busiestHourInt = 0;
        int maxEntries = -1;
        for (int i = 0; i < 24; i++) {
            if (hourCounts[i] > maxEntries) {
                maxEntries = hourCounts[i];
                busiestHourInt = i;
            }
        }
        System.out.println("Busiest Hour: " + String.format("%02d:00", busiestHourInt) + " (" + maxEntries + " entries)");
    }
}

use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn main() {
    // 1. Make an HTTP GET request to http://127.0.0.1:18923/api/products
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut response = String::new();
    stream.read_to_string(&mut response).expect("Failed to read response");

    // 2. Parse the JSON response
    // Split headers and body
    let body = if let Some(b) = response.split("\r\n\r\n").nth(1) {
        b
    } else {
        ""
    };

    let mut products = Vec::new();
    let mut current_obj = String::new();
    let mut in_obj = false;

    // Simple manual JSON parser for the specified object structure
    for c in body.chars() {
        if c == '{' {
            in_obj = true;
            current_obj.clear();
        }
        if in_obj {
            current_obj.push(c);
        }
        if c == '}' && in_obj {
            let obj = &current_obj;

            // Extract name
            let name = {
                let key = "\"name\":";
                if let Some(start) = obj.find(key) {
                    let after_key = &obj[start + key.len()..];
                    if let Some(q_start) = after_key.find('"') {
                        let after_q_start = &after_key[q_start + 1..];
                        if let Some(q_end) = after_q_start.find('"') {
                            after_q_start[..q_end].to_string()
                        } else { String::new() }
                    } else { String::new() }
                } else { String::new() }
            };

            // Extract price
            let price = {
                let key = "\"price\":";
                if let Some(start) = obj.find(key) {
                    let after_key = &obj[start + key.len()..];
                    let trimmed = after_key.trim();
                    let end = trimmed.find(|c: char| !c.is_digit(10) && c != '.' && c != '-').unwrap_or(trimmed.len());
                    trimmed[..end].parse::<f64>().unwrap_or(0.0)
                } else { 0.0 }
            };

            products.push(Product { name, price });
            in_obj = false;
        }
    }

    // 3. Filter to only products where price > 50.00
    let mut filtered: Vec<Product> = products
        .into_iter()
        .filter(|p| p.price > 50.0)
        .collect();

    // 4. Sort filtered products by name ascending
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    // 5. Print the output in the exact format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total = 0.0;
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
        total += p.price;
    }

    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    char name[256];
    double price;
} Product;

int compare_products(const void *a, const void *b) {
    const Product *p1 = (const Product *)a;
    const Product *p2 = (const Product *)b;
    return strcmp(p1->name, p2->name);
}

int main(void) {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char *request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        return 1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(18923);
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        close(sock);
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        close(sock);
        return 1;
    }

    send(sock, request, strlen(request), 0);

    char *response = malloc(1024 * 1024);
    if (!response) {
        close(sock);
        return 1;
    }

    int total_received = 0;
    int n;
    while ((n = recv(sock, response + total_received, 1024 * 1024 - 1 - total_received, 0)) > 0) {
        total_received += n;
    }
    response[total_received] = '\0';
    close(sock);

    char *body = strstr(response, "\r\n\r\n");
    if (body) {
        body += 4;
    } else {
        body = response;
    }

    Product *filtered = malloc(sizeof(Product) * 1000);
    int count = 0;
    double total_sum = 0.0;

    char *ptr = body;
    while ((ptr = strchr(ptr, '{')) != NULL) {
        char *end_obj = strchr(ptr, '}');
        if (!end_obj) break;

        Product current_prod = {0};
        int found_name = 0, found_price = 0;

        char *name_key = strstr(ptr, "\"name\"");
        if (name_key && name_key < end_obj) {
            char *n_start_search = strchr(name_key, ':');
            if (n_start_search && n_start_search < end_obj) {
                char *n_start = strchr(n_start_search, '\"');
                if (n_start && n_start < end_obj) {
                    n_start++;
                    char *n_end = strchr(n_start, '\"');
                    if (n_end && n_end < end_obj) {
                        int len = n_end - n_start;
                        if (len < 255) {
                            memcpy(current_prod.name, n_start, len);
                            current_prod.name[len] = '\0';
                            found_name = 1;
                        }
                    }
                }
            }
        }

        char *price_key = strstr(ptr, "\"price\"");
        if (price_key && price_key < end_obj) {
            char *p_start_search = strchr(price_key, ':');
            if (p_start_search && p_start_search < end_obj) {
                char *p_start = p_start_search + 1;
                while (*p_start == ' ' && p_start < end_obj) p_start++;
                char *p_end = p_start;
                while (p_end < end_obj && *p_end != ',' && *p_end != '}' && *p_end != ' ') p_end++;

                char price_buf[64] = {0};
                int p_len = p_end - p_start;
                if (p_len < 63) {
                    memcpy(price_buf, p_start, p_len);
                    current_prod.price = atof(price_buf);
                    found_price = 1;
                }
            }
        }

        if (found_name && found_price && current_prod.price > 50.0) {
            filtered[count++] = current_prod;
            total_sum += current_prod.price;
        }
        ptr = end_obj + 1;
    }

    qsort(filtered, count, sizeof(Product), compare_products);

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    for (int i = 0; i < count; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
    }
    printf("\nCount: %d\nTotal: $%.2f\n", count, total_sum);

    free(response);
    free(filtered);

    return 0;
}

import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

function main() {
    const filePath = '/tmp/…/graph.json';
    let data: GraphData;

    try {
        const fileContent = fs.readFileSync(filePath, 'utf8');
        data = JSON.parse(fileContent);
    } catch (e) {
        return;
    }

    const adj = new Map<string, {node: string, weight: number}[]>();
    for (const node of data.nodes) {
        adj.set(node, []);
    }

    for (const edge of data.edges) {
        const fromAdj = adj.get(edge.from);
        if (fromAdj) {
            fromAdj.push({node: edge.to, weight: edge.weight});
        }
        const toAdj = adj.get(edge.to);
        if (toAdj) {
            toAdj.push({node: edge.from, weight: edge.weight});
        }
    }

    const distances = new Map<string, number>();
    const visited = new Set<string>();

    for (const node of data.nodes) {
        distances.set(node, Infinity);
    }

    if (data.nodes.includes("A")) {
        distances.set("A", 0);
    } else {
        // If A is not in the nodes list, it's still the source.
        // We'll manually add it to the distances map for the output.
        distances.set("A", 0);
    }

    const allNodes = data.nodes.includes("A") ? data.nodes : ["A", ...data.nodes];

    while (visited.size < allNodes.length) {
        let u: string | null = null;
        let minDist = Infinity;

        for (const node of allNodes) {
            if (!visited.has(node)) {
                const d = distances.get(node) ?? Infinity;
                if (d < minDist) {
                    minDist = d;
                    u = node;
                }
            }
        }

        if (u === null) break;

        visited.add(u);

        const neighbors = adj.get(u) || [];
        for (const neighbor of neighbors) {
            const alt = (distances.get(u) ?? Infinity) + neighbor.weight;
            if (alt < (distances.get(neighbor.node) ?? Infinity)) {
                distances.set(neighbor.node, alt);
            }
        }
    }

    process.stdout.write("=== Shortest Paths from A ===\n\n");
    const sortedNodes = [...allNodes].sort();
    for (const node of sortedNodes) {
        const dist = distances.get(node);
        process.stdout.write(`A -> ${node}: ${dist}\n`);
    }
}

