public class Main {
    static class FileStats {
        String path;
        long lines;
        long bytes;

        FileStats(String path, long lines, long bytes) {
            this.path = path;
            this.lines = lines;
            this.bytes = bytes;
        }
    }

    public static void main(String[] args) {
        String rootDir = "/tmp/…/project_tree";
        Path rootPath = Paths.get(rootDir);
        TreeMap<String, List<FileStats>> extensionGroups = new TreeMap<>();

        try (Stream<Path> paths = Files.walk(rootPath)) {
            paths.filter(Files::isRegularFile).forEach(path -> {
                String fileName = path.getFileName().toString();
                int dotIndex = fileName.lastIndexOf('.');
                String ext = (dotIndex == -1) ? "" : fileName.substring(dotIndex);

                try {
                    long lineCount;
                    try (Stream<String> linesStream = Files.lines(path)) {
                        lineCount = linesStream.count();
                    }
                    long byteCount = Files.size(path);
                    String relPath = rootPath.relativize(path).toString().replace('\\', '/');

                    extensionGroups.computeIfAbsent(ext, k -> new ArrayList<>())
                                    .add(new FileStats(relPath, lineCount, byteCount));
                } catch (IOException e) {
                    // Ignore files that cannot be read
                }
            });
        } catch (IOException e) {
            // Ignore errors accessing the root directory
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalBytes = 0;

        for (Map.Entry<String, List<FileStats>> entry : extensionGroups.entrySet()) {
            String ext = entry.getKey();
            List<FileStats> files = entry.getValue();
            Collections.sort(files, Comparator.comparing(f -> f.path));

            long extLines = 0;
            long extBytes = 0;
            for (FileStats f : files) {
                extLines += f.lines;
                extBytes += f.bytes;
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files.size());
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extBytes);
            for (FileStats f : files) {
                System.out.println("    " + f.path + ": " + f.lines + " lines, " + f.bytes + " chars");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalBytes += extBytes;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalBytes + " characters");
    }
}

