import Foundation

func isEqual(_ a: Any, _ b: Any) -> Bool {
    if let aS = a as? String, let bS = b as? String { return aS == bS }
    if let aN = a as? NSNumber, let bN = b as? NSNumber { return aN == bN }
    if let aB = a as? Bool, let bB = b as? Bool { return aB == bB }
    if let aD = a as? [String: Any], let bD = b as? [String: Any] {
        if aD.count != bD.count { return false }
        for (k, v) in aD {
            guard let bv = bD[k], isEqual(v, bv) else { return false }
        }
        return true
    }
    if let aA = a as? [Any], let bA = b as? [Any] {
        if aA.count != bA.count { return false }
        for i in 0..<aA.count {
            if !isEqual(aA[i], bA[i]) { return false }
        }
        return true
    }
    return false
}

func deepMerge(a: Any, b: Any) -> Any {
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        var merged = aDict
        for (k, vB) in bDict {
            if let vA = merged[k] {
                merged[k] = deepMerge(a: vA, b: vB)
            } else {
                merged[k] = vB
            }
        }
        return merged
    } else if let aArr = a as? [Any], let bArr = b as? [Any] {
        var unique = [Any]()
        for item in (aArr + bArr) {
            if !unique.contains(where: { isEqual($0, item) }) {
                unique.append(item)
            }
        }
        return unique
    } else {
        return b
    }
}

func formatJSON(_ value: Any, indent: String = "", nextIndent: String = "  ") -> String {
    if let dict = value as? [String: Any] {
        let sortedKeys = dict.keys.sorted()
        if sortedKeys.isEmpty { return "{}" }
        var result = "{\n"
        for (index, key) in sortedKeys.enumerated() {
            let val = dict[key]!
            result += "\(indent)\(nextIndent)\"\(key)\": \(formatJSON(val, indent: nextIndent, nextIndent: nextIndent + "  "))"
            if index < sortedKeys.count - 1 {
                result += ","
            }
            result += "\n"
        }
        result += "\(indent)}"
        return result
    } else if let array = value as? [Any] {
        if array.isEmpty { return "[]" }
        var result = "[\n"
        for (index, item) in array.enumerated() {
            result += "\(indent)\(nextIndent)\(formatJSON(item, indent: nextIndent, nextIndent: nextIndent + "  "))"
            if index < array.count - 1 {
                result += ","
            }
            result += "\n"
        }
        result += "\(indent)]"
        return result
    } else {
        if let data = try? JSONSerialization.data(withJSONObject: value, options: []),
           let s = String(data: data, encoding: .utf8) {
            return s
        }
        return "null"
    }
}

