public class Main {
    static class Edge {
        String to;
        int weight;
        Edge(String to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class NodeDist implements Comparable<NodeDist> {
        String node;
        int dist;
        NodeDist(String node, int dist) {
            this.node = node;
            this.dist = dist;
        }
        @Override
        public int compareTo(NodeDist other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    public static void main(String[] args) {
        try {
            String filePath = "/tmp/…/graph.json";
            String content = new String(Files.readAllBytes(Paths.get(filePath)));

            // Parse nodes
            int nodesKeyIdx = content.indexOf("\"nodes\":");
            int nodesStart = content.indexOf("[", nodesKeyIdx);
            int nodesEnd = content.indexOf("]", nodesStart);
            String nodesPart = content.substring(nodesStart + 1, nodesEnd);
            String[] nodeArray = nodesPart.split(",");
            List<String> nodes = new ArrayList<>();
            for (String n : nodeArray) {
                nodes.add(n.trim().replace("\"", ""));
            }

            // Adjacency list for undirected weighted graph
            Map<String, List<Edge>> adj = new HashMap<>();
            for (String node : nodes) {
                adj.put(node, new ArrayList<>());
            }

            // Parse edges
            int edgesKeyIdx = content.indexOf("\"edges\":");
            int edgesStart = content.indexOf("[", edgesKeyIdx);
            int edgesEnd = content.lastIndexOf("]");
            if (edgesStart != -1 && edgesEnd != -1) {
                String edgesPart = content.substring(edgesStart + 1, edgesEnd);
                int i = 0;
                while (i < edgesPart.length()) {
                    int open = edgesPart.indexOf("{", i);
                    if (open == -1) break;
                    int close = edgesPart.indexOf("}", open);
                    String block = edgesPart.substring(open + 1, close);
                    String[] pairs = block.split(",");
                    String from = "", to = "";
                    int weight = 0;
                    for (String pair : pairs) {
                        String[] kv = pair.split(":");
                        if (kv.length < 2) continue;
                        String k = kv[0].trim().replace("\"", "");
                        String v = kv[1].trim().replace("\"", "");
                        if (k.equals("from")) from = v;
                        else if (k.equals("to")) to = v;
                        else if (k.equals("weight")) weight = Integer.parseInt(v.trim());
                    }
                    if (!from.isEmpty() && !to.isEmpty()) {
                        if (adj.containsKey(from)) adj.get(from).add(new Edge(to, weight));
                        if (adj.containsKey(to)) adj.get(to).add(new Edge(from, weight));
                    }
                    i = close + 1;
                }
            }

            // Dijkstra's Algorithm
            Map<String, Integer> distances = new HashMap<>();
            for (String node : nodes) {
                distances.put(node, Integer.MAX_VALUE);
            }

            if (distances.containsKey("A")) {
                distances.put("A", 0);
                PriorityQueue<NodeDist> pq = new PriorityQueue<>();
                pq.add(new NodeDist("A", 0));

                while (!pq.isEmpty()) {
                    NodeDist current = pq.poll();
                    String u = current.node;
                    int d = current.dist;

                    if (d > distances.get(u)) continue;

                    for (Edge edge : adj.get(u)) {
                        if (distances.get(u) != Integer.MAX_VALUE && distances.get(u) + edge.weight < distances.get(edge.to)) {
                            distances.put(edge.to, distances.get(u) + edge.weight);
                            pq.add(new NodeDist(edge.to, distances.get(edge.to)));
                        }
                    }
                }
            }

            // Final Output
            System.out.println("=== Shortest Paths from A ===");
            System.out.println();
            Collections.sort(nodes);
            for (String node : nodes) {
                System.out.println("A -> " + node + ": " + distances.get(node));
            }
        } catch (Exception e) {
            // Silence errors for competitive-style prompt
        }
    }
}

