import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try {
            String contentA = Files.readString(Path.of("/tmp/…/config_a.json"));
            String contentB = Files.readString(Path.of("/tmp/…/config_b.json"));

            JsonParser parserA = new JsonParser(contentA);
            JsonParser parserB = new JsonParser(contentB);

            Object jsonA = parserA.parse();
            Object jsonB = parserB.parse();

            Object merged = deepMerge(jsonA, jsonB);

            System.out.println(serialize(merged, 0));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static Object deepMerge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> mapA = (Map<String, Object>) a;
            Map<String, Object> mapB = (Map<String, Object>) b;
            TreeMap<String, Object> result = new TreeMap<>(mapA);
            for (Map.Entry<String, Object> entry : mapB.entrySet()) {
                String key = entry.getKey();
                Object valB = entry.getValue();
                if (result.containsKey(key)) {
                    result.put(key, deepMerge(result.get(key), valB));
                } else {
                    result.put(key, valB);
                }
            }
            return result;
        } else if (a instanceof List && b instanceof List) {
            List<Object> listA = (List<Object>) a;
            List<Object> listB = (List<Object>) b;
            List<Object> result = new ArrayList<>(listA);
            for (Object valB : listB) {
                if (!containsDeep(result, valB)) {
                    result.add(valB);
                }
            }
            return result;
        } else {
            return b;
        }
    }

    private static boolean containsDeep(List<Object> list, Object val) {
        for (Object item : list) {
            if (deepEquals(item, val)) return true;
        }
        return false;
