use std::collections::{BinaryHeap, HashMap};
use std::cmp::Ordering;
use std::fs;

#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    cost: u32,
    node: usize,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
            .then_with(|| self.node.cmp(&other.node))
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("Unable to read file");

    let mut nodes = Vec::new();
    if let Some(nodes_start) = content.find("\"nodes\"") {
        if let Some(bracket_start) = content[nodes_start..].find('[') {
            let actual_start = nodes_start + bracket_start;
            if let Some(bracket_end) = content[actual_start..].find(']') {
                let nodes_str = &content[actual_start + 1..actual_start + bracket_end];
                for n in nodes_str.split(',') {
                    let trimmed = n.trim().trim_matches('"');
                    if !trimmed.is_empty() {
                        nodes.push(trimmed.to_string());
                    }
                }
            }
        }
    }

    let mut edges = Vec::new();
    if let Some(edges_start) = content.find("\"edges\"") {
        if let Some(bracket_start) = content[edges_start..].find('[') {
            let actual_start = edges_start + bracket_start;
            if let Some(bracket_end) = content[actual_start..].find(']') {
                let edges_str = &content[actual_start + 1..actual_start + bracket_end];
                let mut i = 0;
                while i < edges_str.len() {
                    if let Some(start) = edges_str[i..].find('{') {
                        let actual_start = i + start;
                        if let Some(end) = edges_str[actual_start..].find('}') {
                            let actual_end = actual_start + end;
                            let obj = &edges_str[actual_start + 1..actual_end];

                            let mut from = String::new();
                            let mut to = String::new();
                            let mut weight = 0;

                            for pair in obj.split(',') {
                                let mut kv = pair.split(':');
                                if let Some(k) = kv.next() {
                                    let key = k.trim().trim_matches('"');
                                    if let Some(v) = kv.next() {
                                        let val = v.trim().trim_matches('"');
                                        match key {
                                            "from" => from = val.to_string(),
                                            "to" => to = val.to_string(),
                                            "weight" => weight = val.parse().unwrap_or(0),
                                            _ => {}
                                        }
                                    }
                                }
                            }
                            if !from.is_empty() && !to.is_empty() {
                                edges.push((from, to, weight));
                            }
                            i = actual_end + 1;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
            }
        }
    }

    let mut node_to_idx = HashMap::new();
    for (i, node) in nodes.iter().enumerate() {
        node_to_idx.insert(node.clone(), i);
    }

    let mut adj = vec![Vec::new(); nodes.len()];
    for (from, to, weight) in edges {
        if let (Some(&u), Some(&v)) = (node_to_idx.get(&from), node_to_idx.get(&to)) {
            adj[u].push((v, weight));
            adj[v].push((u, weight));
        }
    }

    let start_node_name = "A";
    let mut dist = vec![u32::MAX; nodes.len()];

    if let Some(&start_idx) = node_to_idx.get(start_node_name) {
        dist[start_idx] = 0;
        let mut pq = BinaryHeap::new();
        pq.push(State { cost: 0, node: start_idx });

        while let Some(State { cost, node }) = pq.pop() {
            if cost > dist[node] {
                continue;
            }

            for &(next_node, weight) in &adj[node] {
                let next_cost = cost.saturating_add(weight);
                if next_cost < dist[next_node] {
                    dist[next_node] = next_cost;
                    pq.push(State { cost: next_cost, node: next_node });
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes = nodes.clone();
    sorted_nodes.sort();

    for node in sorted_nodes {
        if let Some(&idx) = node_to_idx.get(&node) {
            let d = dist[idx];
            if d == u32::MAX {
                println!("A -> {}: infinity", node);
            } else {
                println!("A -> {}: {}", node, d);
            }
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

const ROOT_DIR = '/tmp/…/project_tree';

interface FileStats {
  path: string;
  lines: number;
  chars: number;
}

interface ExtStats {
  files: FileStats[];
  totalLines: number;
  totalChars: number;
}

const statsMap = new Map<string, ExtStats>();

function walk(dir: string) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      walk(fullPath);
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name);
      const relativePath = path.relative(ROOT_DIR, fullPath).replace(/\\/g, '/');
      const buffer = fs.readFileSync(fullPath);
      const content = buffer.toString('utf8');
      const lines = content.length === 0 ? 0 : content.split('\n').length;
      const chars = buffer.length;

      if (!statsMap.has(ext)) {
        statsMap.set(ext, { files: [], totalLines: 0, totalChars: 0 });
      }
      const extStats = statsMap.get(ext)!;
      extStats.files.push({ path: relativePath, lines, chars });
      extStats.totalLines += lines;
      extStats.totalChars += chars;
    }
  }
}

walk(ROOT_DIR);

process.stdout.write('=== File Tree Analysis ===\n\n');

const sortedExts = Array.from(statsMap.keys()).sort();
let grandTotalFiles = 0;
let grandTotalLines = 0;
let grandTotalChars = 0;

for (const ext of sortedExts) {
  const extStats = statsMap.get(ext)!;
  extStats.files.sort((a, b) => a.path.localeCompare(b.path));

  process.stdout.write(`Extension: ${ext}\n`);
  process.stdout.write(`  Files: ${extStats.files.length}\n`);
  process.stdout.write(`  Total Lines: ${extStats.totalLines}\n`);
  process.stdout.write(`  Total Characters: ${extStats.totalChars}\n`);
  for (const file of extStats.files) {
    process.stdout.write(`    ${file.path}: ${file.lines} lines, ${file.chars} chars\n`);
  }

  grandTotalFiles += extStats.files.length;
  grandTotalLines += extStats.totalLines;
  grandTotalChars += extStats.totalChars;
}

process.stdout.write(`\nTotal: ${grandTotalFiles} files, ${grandTotalLines} lines, ${grandTotalChars} characters\n`);

