#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int to;
    int weight;
} Edge;

typedef struct {
    Edge *edges;
    int size;
    int capacity;
} AdjList;

void add_edge(AdjList *adj, int u, int v, int w) {
    if (adj[u].size == adj[u].capacity) {
        adj[u].capacity = adj[u].capacity == 0 ? 4 : adj[u].capacity * 2;
        adj[u].edges = realloc(adj[u].edges, adj[u].capacity * sizeof(Edge));
    }
    adj[u].edges[adj[u].size++] = (Edge){v, w};
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int get_node_id(char *name, char **node_names, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        if (strcmp(node_names[i], name) == 0) return i;
    }
    return -1;
}

char *find_string_value(char *start, char *end, const char *key) {
    char key_with_quotes[64];
    sprintf(key_with_quotes, "\"%s\"", key);
    char *k = strstr(start, key_with_quotes);
    if (!k || k >= end) return NULL;
    char *colon = strchr(k, ':');
    if (!colon || colon >= end) return NULL;
    char *quote_start = strchr(colon, '"');
    if (!quote_start || quote_start >= end) return NULL;
    char *quote_end = strchr(quote_start + 1, '"');
    if (!quote_end || quote_end >= end) return NULL;
    int len = quote_end - (quote_start + 1);
    char *res = malloc(len + 1);
    strncpy(res, quote_start + 1, len);
    res[len] = '\0';
    return res;
}

int find_int_value(char *start, char *end, const char *key) {
    char key_with_quotes[64];
    sprintf(key_with_quotes, "\"%s\"", key);
    char *k = strstr(start, key_with_quotes);
    if (!k || k >= end) return 0;
    char *colon = strchr(k, ':');
    if (!colon || colon >= end) return 0;
    int val = 0;
    sscanf(colon + 1, "%d", &val);
    return val;
}

int main(void) {
    FILE *fp = fopen("/tmp/…/graph.json", "r");
    if (!fp) return 1;
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    rewind(fp);
    char *buffer = malloc(size + 1);
    if (!buffer) return 1;
    fread(buffer, 1, size, fp);
    buffer[size] = '\0';
    fclose(fp);

    char *nodes_start = strstr(buffer, "\"nodes\":");
    if (!nodes_start) return 1;
    char *start_bracket = strchr(nodes_start, '[');
    char *end_bracket = strchr(start_bracket, ']');
    int num_nodes = 0;
    char *ptr = start_bracket + 1;
    while (ptr < end_bracket) {
        if (*ptr == '"') {
            num_nodes++;
            ptr = strchr(ptr + 1, '"');
            if (ptr) ptr++;
        } else {
            ptr++;
        }
    }

    char **node_names = malloc(num_nodes * sizeof(char *));
    ptr = start_bracket + 1;
    int node_idx = 0;
    while (ptr < end_bracket && node_idx < num_nodes) {
        if (*ptr == '"') {
            ptr++;
            char *end_q = strchr(ptr, '"');
            int len = end_q - ptr;
            node_names[node_idx] = malloc(len + 1);
            strncpy(node_names[node_idx], ptr, len);
            node_names[node_idx][len] = '\0';
            node_idx++;
            ptr = end_q + 1;
        } else {
            ptr++;
        }
    }
    qsort(node_names, num_nodes, sizeof(char *), compare_strings);

    char *edges_start = strstr(buffer, "\"edges\":");
    if (!edges_start) return 1;
    char *e_start_bracket = strchr(edges_start, '[');
    char *e_end_bracket = strchr(e_start_bracket, ']');
    AdjList *adj = calloc(num_nodes, sizeof(AdjList));
    ptr = e_start_bracket + 1;
    while (ptr < e_end_bracket) {
        if (*ptr == '{') {
            ptr++;
            char *block_end = strchr(ptr, '}');
            char *from_name = find_string_value(ptr, block_end, "from");
            char *to_name = find_string_value(ptr, block_end, "to");
            int weight = find_int_value(ptr, block_end, "weight");
            int u = get_node_id(from_name, node_names, num_nodes);
            int v = get_node_id(to_name, node_names, num_nodes);
            if (u != -1 && v != -1) {
                add_edge(adj, u, v, weight);
                add_edge(adj, v, u, weight);
            }
            free(from_name);
            free(to_name);
            ptr = block_end + 1;
        } else {
            ptr++;
        }
    }

    int start_node_idx = get_node_id("A", node_names, num_nodes);
    long long *dist = malloc(num_nodes * sizeof(long long));
    int *visited = calloc(num_nodes, sizeof(int));
    for (int i = 0; i < num_nodes; i++) dist[i] = LLONG_MAX;
    if (start_node_idx != -1) dist[start_node_idx] = 0;

    for (int i = 0; i < num_nodes; i++) {
        int u = -1;
        for (int j = 0; j < num_nodes; j++) {
            if (!visited[j] && (u == -1 || dist[j] < dist[u])) {
                u = j;
            }
        }
        if (u == -1 || dist[u] == LLONG_MAX) break;
        visited[u] = 1;
        for (int j = 0; j < adj[u].size; j++) {
            int v = adj[u].edges[j].to;
            int w = adj[u].edges[j].weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }

    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < num_nodes; i++) {
        printf("A -> %s: ", node_names[i]);
        if (dist[i] == LLONG_MAX) printf("INF\n");
        else printf("%lld\n", dist[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char *path;
    long lines;
    long chars;
} FileInfo;

typedef struct {
    char *ext;
    FileInfo *files;
    int file_count;
    int file_capacity;
    long total_lines;
    long total_chars;
} ExtGroup;

ExtGroup *groups = NULL;
int group_count = 0;
int group_capacity = 0;

char *my_strdup(const char *s) {
    if (!s) return NULL;
    size_t len = strlen(s) + 1;
    char *d = malloc(len);
    if (d) memcpy(d, s, len);
    return d;
}

const char *get_ext(const char *path) {
    const char *filename = strrchr(path, '/');
    if (!filename) filename = path; else filename++;
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return "";
    return dot;
}

void add_to_group(const char *ext, const char *rel_path, long lines, long chars) {
    for (int i = 0; i < group_count; i++) {
        if (strcmp(groups[i].ext, ext) == 0) {
            ExtGroup *g = &groups[i];
            if (g->file_count == g->file_capacity) {
                g->file_capacity *= 2;
                g->files = realloc(g->files, sizeof(FileInfo) * g->file_capacity);
            }
            g->files[g->file_count].path = my_strdup(rel_path);
            g->files[g->file_count].lines = lines;
            g->files[g->file_count].chars = chars;
            g->file_count++;
            g->total_lines += lines;
            g->total_chars += chars;
            return;
        }
    }
    if (group_count == group_capacity) {
        group_capacity = (group_capacity == 0) ? 10 : group_capacity * 2;
        groups = realloc(groups, sizeof(ExtGroup) * group_capacity);
    }
    ExtGroup *g = &groups[group_count++];
    g->ext = my_strdup(ext);
    g->file_capacity = 10;
    g->files = malloc(sizeof(FileInfo) * g->file_capacity);
    g->file_count = 0;
    g->total_lines = 0;
    g->total_chars = 0;
    g->files[g->file_count].path = my_strdup(rel_path);
    g->files[g->file_count].lines = lines;
    g->files[g->file_count].chars = chars;
    g->file_count++;
    g->total_lines = lines;
    g->total_chars = chars;
}

void process_file(const char *full_path, const char *rel_path) {
    FILE *fp = fopen(full_path, "rb");
    if (!fp) return;
    long lines = 0, chars = 0;
    unsigned char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') lines++;
        }
        chars += n;
    }
    fclose(fp);
    add_to_group(get_ext(rel_path), rel_path, lines, chars);
}

void walk(const char *base_path, const char *rel_path) {
    char full_path[4096];
    if (rel_path == NULL || strlen(rel_path) == 0) {
        strncpy(full_path, base_path, sizeof(full_path));
    } else {
        snprintf(full_path, sizeof(full_path), "%s/%s", base_path, rel_path);
    }

    DIR *dir = opendir(full_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char next_rel_path[4096];
        if (rel_path == NULL || strlen(rel_path) == 0) {
            strncpy(next_rel_path, entry->d_name, sizeof(next_rel_path));
        } else {
            snprintf(next_rel_path, sizeof(next_rel_path), "%s/%s", rel_path, entry->d_name);
        }

        char next_full_path[4096];
        snprintf(next_full_path, sizeof(next_full_path), "%s/%s", base_path, next_rel_path);

        struct stat st;
        if (lstat(next_full_path, &st) != 0) continue;

        if (S_ISDIR(st.st_mode)) {
            walk(base_path, next_rel_path);
        } else if (S_ISREG(st.st_mode)) {
            process_file(next_full_path, next_rel_path);
        }
    }
    closedir(dir);
}

int compare_ext(const void *a, const void *b) {
    return strcmp(((ExtGroup *)a)->ext, ((ExtGroup *)b)->ext);
}

int compare_files(const void *a, const void *b) {
    return strcmp(((FileInfo *)a)->path, ((FileInfo *)b)->path);
}

int main(void) {
    const char *root_path = "/tmp/…/project_tree";
    walk(root_path, "");

    qsort(groups, group_count, sizeof(ExtGroup), compare_ext);

    printf("=== File Tree Analysis ===\n\n");
    long grand_total_files = 0, grand_total_lines = 0, grand_total_chars = 0;

    for (int i = 0; i < group_count; i++) {
        qsort(groups[i].files, groups[i].file_count, sizeof(FileInfo), compare_files);
        printf("Extension: %s\n", groups[i].ext);
        printf("  Files: %d\n", groups[i].file_count);
        printf("  Total Lines: %ld\n", groups[i].total_lines);
        printf("  Total Characters: %ld\n", groups[i].total_chars);
        for (int j = 0; j < groups[i].file_count; j++) {
            printf("    %s: %ld lines, %ld chars\n", groups[i].files[j].path, groups[i].files[j].lines, groups[i].files[j].chars);
        }
        grand_total_files += groups[i].file_count;
        grand_total_lines += groups[i].total_lines;
        grand_total_chars += groups[i].total_chars;
    }

    printf("\nTotal: %ld files, %ld lines, %ld characters\n", grand_total_files, grand_total_lines, grand_total_chars);

    for (int i = 0; i < group_count; i++) {
        free(groups[i].ext);
        for (int j = 0; j < groups[i].file_count; j++) {
            free(groups[i].files[j].path);
        }
        free(groups[i].files);
    }
    free(groups);

    return 0;
}

