                for (int k = 0; k < 3; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }

        long det = (long) C[0][0] * ((long) C[1][1] * C[2][2] - (long) C[1][2] * C[2][1])
                 - (long) C[0][1] * ((long) C[1][0] * C[2][2] - (long) C[1][2] * C[2][0])
                 + (long) C[0][2] * ((long) C[1][0] * C[2][1] - (long) C[1][1] * C[2][0]);

