use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

struct FileInfo {
    lines: usize,
    chars: usize,
}

struct ExtGroup {
    files: Vec<(String, FileInfo)>,
    total_lines: usize,
    total_chars: usize,
}

fn walk_dir(dir: &Path, base_path: &Path, stats_map: &mut BTreeMap<String, ExtGroup>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            let metadata = match path.symlink_metadata() {
                Ok(m) => m,
                Err(_) => continue,
            };

            if metadata.is_dir() {
                walk_dir(&path, base_path, stats_map);
            } else if metadata.is_file() {
                let ext = path.extension()
                    .map(|e| e.to_string_lossy().into_owned())
                    .unwrap_or_default();

                let ext_key = if ext.is_empty() {
                    "".to_string()
                } else {
                    format!(".{}", ext)
                };

                if let Ok(content) = fs::read(&path) {
                    let mut line_count = 0;
                    let mut last_was_newline = true;
                    for &b in &content {
                        if b == b'\n' {
                            line_count += 1;
                            last_was_newline = true;
                        } else {
                            last_was_newline = false;
                        }
                    }
                    if !last_was_newline {
                        line_count += 1;
                    }

                    let char_count = content.len();
                    let rel_path = path.strip_prefix(base_path)
                        .map(|p| p.to_string_lossy().into_owned())
                        .unwrap_or_default();

                    let group = stats_map.entry(ext_key).or_insert(ExtGroup {
                        files: Vec::new(),
                        total_lines: 0,
                        total_chars: 0,
                    });
                    group.files.push((rel_path, FileInfo { lines: line_count, chars: char_count }));
                    group.total_lines += line_count;
                    group.total_chars += char_count;
                }
            }
        }
    }
}

fn main() {
    let base_path = Path::new("/tmp/…/project_tree");
    let mut stats_map: BTreeMap<String, ExtGroup> = BTreeMap::new();

    walk_dir(base_path, base_path, &mut stats_map);

    println!("=== File Tree Analysis ===");
    println!();

    let mut grand_total_files = 0;
    let mut grand_total_lines = 0;
    let mut grand_total_chars = 0;

    for (ext, group) in stats_map {
        let mut sorted_files = group.files;
        sorted_files.sort_by(|a, b| a.0.cmp(&b.0));

        println!("Extension: {}", ext);
        println!("  Files: {}", sorted_files.len());
        println!("  Total Lines: {}", group.total_lines);
        println!("  Total Characters: {}", group.total_chars);

