#include <stdio.h>
#include <stdlib.h>

/**
 * Function to allocate a 3x3 matrix dynamically.
 */
int** allocateMatrix() {
    int** matrix = (int**)malloc(3 * sizeof(int*));
    for (int i = 0; i < 3; i++) {
        matrix[i] = (int*)malloc(3 * sizeof(int));
    }
    return matrix;
}

/**
 * Function to print a 3x3 matrix according to the specified format.
 */
void printMatrix(int** matrix) {
    for (int i = 0; i < 3; i++) {
        printf("  ");
        for (int j = 0; j < 3; j++) {
            printf("%4d", matrix[i][j]);
            if (j < 2) {
                printf(" ");
            }
        }
        printf("\n");
    }
}

/**
 * Performs standard matrix multiplication C = A x B for 3x3 matrices.
 */
void multiplyMatrices(int** A, int** B, int** C) {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

/**
 * Computes the determinant of a 3x3 matrix.
 */
long computeDeterminant(int** m) {
    return (long)m[0][0] * ((long)m[1][1] * m[2][2] - (long)m[1][2] * m[2][1]) -
           (long)m[0][1] * ((long)m[1][0] * m[2][2] - (long)m[1][2] * m[2][0]) +
           (long)m[0][2] * ((long)m[1][0] * m[2][1] - (long)m[1][1] * m[2][0]);
}

int main(void) {
    int** A = allocateMatrix();
    int** B = allocateMatrix();
    int** C = allocateMatrix();

    // Define Matrix A
    A[0][0] = 1; A[0][1] = 2; A[0][2] = 3;
    A[1][0] = 4; A[1][1] = 5; A[1][2] = 6;
    A[2][0] = 7; A[2][1] = 8; A[2][2] = 9;

    // Define Matrix B
    B[0][0] = 9; B[0][1] = 8; B[0][2] = 7;
    B[1][0] = 6; B[1][1] = 5; B[1][2] = 4;
    B[2][0] = 3; B[2][1] = 2; B[2][2] = 1;

    // Compute C = A x B
    multiplyMatrices(A, B, C);

    // Compute determinant of C
    long detC = computeDeterminant(C);

    // Output results in the exact specified format
    printf("=== Matrix Operations ===\n\n");

    printf("Matrix A:\n");
    printMatrix(A);

    printf("\nMatrix B:\n");
    printMatrix(B);

    printf("\nA x B =\n");
    printMatrix(C);

    printf("\nDeterminant: %ld\n", detC);

    // Clean up allocated memory
    for (int i = 0; i < 3; i++) {
        free(A[i]);
        free(B[i]);
        free(C[i]);
    }
    free(A);
    free(B);
    free(C);

    return 0;
}

func formatValue(_ v: Int) -> String {
    let s = String(v)
    let len = s.count
    if len >= 4 { return s }
    return String(repeating: " ", count: 4 - len) + s
}

func multiply(_ m1: [[Int]], _ m2: [[Int]]) -> [[Int]] {
    let rows1 = m1.count
    let cols1 = m1[0].count
    let cols2 = m2[0].count
    var result = Array(repeating: Array(repeating: 0, count: cols2), count: rows1)
    for i in 0..<rows1 {
        for j in 0..<cols2 {
            for k in 0..<cols1 {
                result[i][j] += m1[i][k] * m2[k][j]
            }
        }
    }
    return result
}

func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0]
    }
    var det = 0
    for j in 0..<n {
        var submatrix = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n {
                if k != j {
                    row.append(m[i][k])
                }
            }
            submatrix.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * m[0][j] * determinant(submatrix)
    }
    return det
}

