use std::collections::BTreeMap;
use std::fs::read_to_string;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    fn peek_char(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.peek_char();
        if c.is_some() {
            self.pos += c.unwrap().len_utf8();
        }
        c
    }

    fn consume_whitespace(&mut self) {
        while let Some(c) = self.peek_char() {
            if c.is_whitespace() {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Value {
        self.consume_whitespace();
        let c = self.peek_char().expect("Unexpected EOF");
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            '0'..='9' | '-' => self.parse_number(),
            _ => panic!("Unexpected character: {}", c),
        }
    }

    fn parse_string(&mut self) -> Value {
        self.next_char(); // skip "
        let mut s = String::new();
        while let Some(c) = self.peek_char() {
            if c == '"' {
                self.next_char();
                return Value::String(s);
            } else if c == '\\' {
                self.next_char();
                if let Some(esc) = self.next_char() {
                    match esc {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        '/' => s.push('/'),
                        'b' => s.push('\x08'),
                        'r' => s.push('\r'),
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        'u' => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                hex.push(self.next_char().expect("Invalid unicode escape"));
                            }
                            let code = u32::from_str_radix(&hex, 16).expect("Invalid hex");
                            s.push(std::char::from_u32(code).expect("Invalid unicode char"));
                        }
                        _ => panic!("Unknown escape sequence"),
                    }
                }
            } else {
                s.push(c);
                self.pos += c.len_utf8();
            }
        }
        panic!("Unclosed string");
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        while let Some(c) = self.peek_char() {
            if c.is_ascii_digit() || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E' {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
        let s = &self.input[start..self.pos];
        Value::Number(s.parse::<f64>().expect("Invalid number"))
    }

    fn parse_bool(&mut self) -> Value {
        if self.input[self.pos..].starts_with("true") {
            self.pos += 4;
            Value::Bool(true)
        } else {
            self.pos += 5;
            Value::Bool(false)
        }
    }

    fn parse_null(&mut self) -> Value {
        self.pos += 4;
        Value::Null
    }

    fn parse_array(&mut self) -> Value {
        self.next_char(); // skip [
        let mut arr = Vec::new();
        loop {
            self.consume_whitespace();
            if let Some(']') = self.peek_char() {
                self.next_char();
                break;
            }
            arr.push(self.parse_value());
            self.consume_whitespace();
            if let Some(',') = self.peek_char() {
                self.next_char();
            } else if let Some(']') = self.peek_char() {
                self.next_char();
                break;
            } else {
                panic!("Expected , or ] in array");
            }
        }
        Value::Array(arr)
    }

    fn parse_object(&mut self) -> Value {
        self.next_char(); // skip {
        let mut map = BTreeMap::new();
        loop {
            self.consume_whitespace();
            if let Some('}') = self.peek_char() {
                self.next_char();
                break;
            }
            let key = match self.peek_char() {
                Some('"') => {
                    let Value::String(s) = self.parse_string();
                    s
                }
                _ => panic!("Expected string key in object"),
            };
            self.consume_whitespace();
            if self.next_char() != Some(':') {
                panic!("Expected : after key");
            }
            let value = self.parse_value();
            map.insert(key, value);
            self.consume_whitespace();
            if let Some(',') = self.peek_char() {
                self.next_char();
            } else if let Some('}') = self.peek_char() {
                self.next_char();
                break;
            } else {
                panic!("Expected , or } in object");
            }
        }
        Value::Object(map)
    }
}

fn merge(a: Value, b: Value) -> Value {
    match (a, b) {
        (Value::Object(mut map_a), Value::Object(map_b)) => {
            for (k, v_b) in map_b {
                if let Some(v_a) = map_a.remove(&k) {
                    map_a.insert(k, merge(v_a, v_b));
                } else {
                    map_a.insert(k, v_b);
                }
            }
            Value::Object(map_a)
        }
        (Value::Array(mut arr_a), Value::Array(arr_b)) => {
            for v_b in arr_b {
                if !arr_a.contains(&v_b) {
                    arr_a.push(v_b);
                }
            }
            Value::Array(arr_a)
        }
        (_, b) => b,
    }
}

