    if (node->type == JSON_STRING) {
        copy->value.s = my_strdup(node->value.s);
    } else if (node->type == JSON_NUMBER) {
        copy->value.n = node->value.n;
    } else if (node->type == JSON_BOOLEAN) {
        copy->value.b = node->value.b;
    } else if (node->type == JSON_NULL) {
        // no value
    } else if (node->type == JSON_ARRAY) {
        copy->value.arr.size = 0;
        copy->value.arr.capacity = 0;
        copy->value.arr.elements = NULL;
        for (size_t i = 0; i < node->value.arr.size; i++) add_to_array(copy, copy_node(node->value.arr.elements[i]));
    } else if (node->type == JSON_OBJECT) {
        copy->value.obj.size = 0;
        copy->value.obj.capacity = 0;
        copy->value.obj.pairs = NULL;
        for (size_t i = 0; i < node->value.obj.size; i++) add_to_object(copy, node->value.obj.pairs[i].key, copy_node(node->value.obj.pairs[i].value));
    }
    return copy;
}

JSONNode* find_value(JSONNode *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (size_t i = 0; i < obj->value.obj.size; i++) {
        if (strcmp(obj->value.obj.pairs[i].key, key) == 0) return obj->value.obj.pairs[i].value;
    }
    return NULL;
}

bool json_equal(JSONNode *a, JSONNode *b) {
    if (!a || !b) return (a == b);
    if (a->type != b->type) return false;
    if (a->type == JSON_STRING) return strcmp(a->value.s, b->value.s) == 0;
    if (a->type == JSON_NUMBER) return a->value.n == b->value.n;
    if (a->type == JSON_BOOLEAN) return a->value.b == b->value.b;
    if (a->type == JSON_NULL) return true;
    if (a->type == JSON_ARRAY) {
        if (a->value.arr.size != b->value.arr.size) return false;
        for (size_t i = 0; i < a->value.arr.size; i++) if (!json_equal(a->value.arr.elements[i], b->value.arr.elements[i])) return false;
        return true;
    }
    if (a->type == JSON_OBJECT) {
        if (a->value.obj.size != b->value.obj.size) return false;
        for (size_t i = 0; i < a->value.obj.size; i++) {
            JSONNode *valB = find_value(b, a->value.obj.pairs[i].key);
            if (!valB || !json_equal(a->value.obj.pairs[i].value, valB)) return false;
        }
        return true;
    }
    return false;
}

JSONNode* merge(JSONNode *a, JSONNode *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JSONNode *res = malloc(sizeof(JSONNode));
        res->type = JSON_OBJECT;
        res->value.obj.size = 0;
        res->value.obj.capacity = 0;
        res->value.obj.pairs = NULL;
        for (size_t i = 0; i < a->value.obj.size; i++) {
            char *key = a->value.obj.pairs[i].key;
            JSONNode *valA = a->value.obj.pairs[i].value;
            JSONNode *valB = find_value(b, key);
            if (valB) add_to_object(res, key, merge(valA, valB));
            else add_to_object(res, key, copy_node(valA));
        }
        for (size_t i = 0; i < b->value.obj.size; i++) {
            char *key = b->value.obj.pairs[i].key;
            if (!find_value(a, key)) add_to_object(res, key, copy_node(b->value.obj.pairs[i].value));
        }
        return res;
    } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JSONNode *res = malloc(sizeof(JSONNode));
        res->type = JSON_ARRAY;
        res->value.arr.size = 0;
        res->value.arr.capacity = 0;
        res->value.arr.elements = NULL;
        for (size_t i = 0; i < a->value.arr.size; i++) add_to_array(res, copy_node(a->value.arr.elements[i]));
        for (size_t i = 0; i < b->value.arr.size; i++) {
            JSONNode *valB = b->value.arr.elements[i];
            bool exists = false;
            for (size_t j = 0; j < res->value.arr.size; j++) if (json_equal(res->value.arr.elements[j], valB)) { exists = true; break; }
            if (!exists) add_to_array(res, copy_node(valB));
        }
        return res;
    }
    return copy_node(b);
}

typedef struct {
    const char *json;
    size_t pos;
} Parser;

void skip_whitespace(Parser *p) {
    while (p->json[p->pos] && (p->json[p->pos] == ' ' || p->json[p->pos] == '\t' || p->json[p->pos] == '\n' || p->json[p->pos] == '\r')) p->pos++;
}

char* parse_string(Parser *p) {
    p->pos++; // "
    size_t cap = 32, len = 0;
    char *buf = malloc(cap);
    while (p->json[p->pos] != '"') {
        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
        if (p->json[p->pos] == '\\') {
            p->pos++;
            switch (p->json[p->pos]) {
                case 'n': buf[len++] = '\n'; break;
                case 'r': buf[len++] = '\r'; break;
                case 't': buf[len++] = '\t'; break;
                case '\"': buf[len++] = '\"'; break;
                case '\\': buf[len++] = '\\'; break;
                default: buf[len++] = p->json[p->pos]; break;
            }
        } else buf[len++] = p->json[p->pos];
        p->pos++;
    }
    p->pos++; // "
    buf[len] = '\0';
    return buf;
}

JSONNode* parse_value(Parser *p);

JSONNode* parse_object(Parser *p) {
    p->pos++; // {
    JSONNode *node = malloc(sizeof(JSONNode));
    node->type = JSON_OBJECT;
    node->value.obj.size = 0;
    node->value.obj.capacity = 0;
    node->value.obj.pairs = NULL;
    skip_whitespace(p);
    while (p->json[p->pos] != '}') {
        char *key = parse_string(p);
        skip_whitespace(p);
        p->pos++; // :
        JSONNode *val = parse_value(p);
        add_to_object(node, key, val);
        free(key);
        skip_whitespace(p);
        if (p->json[p->pos] == ',') { p->pos++; skip_whitespace(p); }
    }
    p->pos++; // }
    return node;
}

JSONNode* parse_array(Parser *p) {
    p->pos++; // [
    JSONNode *node = malloc(sizeof(JSONNode));
    node->type = JSON_ARRAY;
    node->value.arr.size = 0;
    node->value.arr.capacity = 0;
    node->value.arr.elements = NULL;
    skip_whitespace(p);
    while (p->json[p->pos] != ']') {
        add_to_array(node, parse_value(p));
        skip_whitespace(p);
        if (p->json[p->pos] == ',') { p->pos++; skip_whitespace(p); }
    }
    p->pos++; // ]
    return node;
}

JSONNode* parse_value(Parser *p) {
    skip_whitespace(p);
    if (p->json[p->pos] == '{') return parse_object(p);
    if (p->json[p->pos] == '[') return parse_array(p);
    if (p->json[p->pos] == '"') {
        char *s = parse_string(p);
        JSONNode *n = malloc(sizeof(JSONNode));
        n->type = JSON_STRING; n->value.s = s; return n;
    }
    if (strncmp(&p->json[p->pos], "true", 4) == 0) {
        p->pos += 4; JSONNode *n = malloc(sizeof(JSONNode)); n->type = JSON_BOOLEAN; n->value.b = true; return n;
    }
    if (strncmp(&p->json[p->pos], "false", 5) == 0) {
        p->pos += 5; JSONNode *n = malloc(sizeof(JSONNode)); n->type = JSON_BOOLEAN; n->value.b = false; return n;
    }
    if (strncmp(&p->json[p->pos], "null", 4) == 0) {
        p->pos += 4; JSONNode *n = malloc(sizeof(JSONNode)); n->type = JSON_NULL; return n;
    }
    char *end;
    double d = strtod(&p->json[p->pos], &end);
    p->pos = end - p->json;
    JSONNode *n = malloc(sizeof(JSONNode));
    n->type = JSON_NUMBER; n->value.n = d; return n;
}

int compare_kv(const void *a, const void *b) {
    return strcmp(((JSONKeyValue*)a)->key, ((JSONKeyValue*)b)->key);
}

void print_json(JSONNode *node, int indent) {
    if (node->type == JSON_STRING) {
        printf("\"");
        for (size_t i = 0; node->value.s[i]; i++) {
            if (node->value.s[i] == '\"') printf("\\\"");
            else if (node->value.s[i] == '\\') printf("\\\\");
            else if (node->value.s[i] == '\n') printf("\\n");
            else if (node->value.s[i] == '\r') printf("\\r");
            else if (node->value.s[i] == '\t') printf("\\t");
            else printf("%c", node->value.s[i]);
        }
        printf("\"");
    } else if (node->type == JSON_NUMBER) printf("%.15g", node->value.n);
    else if (node->type == JSON_BOOLEAN) printf("%s", node->value.b ? "true" : "false");
    else if (node->type == JSON_NULL) printf("null");
    else if (node->type == JSON_ARRAY) {
        printf("[");
        for (size_t i = 0; i < node->value.arr.size; i++) {
            if (i > 0) printf(", ");
            print_json(node->value.arr.elements[i], indent);
        }
        printf("]");
    } else if (node->type == JSON_OBJECT) {
        qsort(node->value.obj.pairs, node->value.obj.size, sizeof(JSONKeyValue), compare_kv);
        printf("{\n");
        for (size_t i = 0; i < node->value.obj.size; i++) {
            for (int j = 0; j < indent + 2; j++) printf(" ");
            printf("\"%s\": ", node->value.obj.pairs[i].key);
            print_json(node->value.obj.pairs[i].value, indent + 2);
            if (i < node->value.obj.size - 1) printf(",");
            printf("\n");
        }
        for (int j = 0; j < indent; j++) printf(" ");
        printf("}");
    }
}

char* read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(len + 1);
    if (buf) {
        size_t read_len = fread(buf, 1, len, f);
        buf[read_len] = '\0';
    }
    fclose(f);
    return buf;
}

int main(void) {
    char *json_a_str = read_file("/tmp/…/config_a.json");
    char *json_b_str = read_file("/tmp/…/config_b.json");
    if (!json_a_str || !json_b_str) return 1;
    Parser p_a = {json_a_str, 0}, p_b = {json_b_str, 0};
    JSONNode *a = parse_value(&p_a);
    JSONNode *b = parse_value(&p_b);
    JSONNode *merged = merge(a, b);
    print_json(merged, 0);
    printf("\n");
    free_node(a); free_node(b); free_node(merged);
    free(json_a_str); free(json_b_str);
    return 0;
}
